test_suite:
test('resolve returns registered instance', () => {
  const c = new Container();
  c.register('val', () => 42);
  expect(c.resolve('val')).toBe(42);
});

test('resolve is singleton — same instance each call', () => {
  const c = new Container();
  c.register('obj', () => ({ x: 1 }));
  expect(c.resolve('obj')).toBe(c.resolve('obj'));
});

test('factory receives container for dependency resolution', () => {
  const c = new Container();
  c.register('a', () => 10);
  c.register('b', (container) => container.resolve('a') * 2);
  expect(c.resolve('b')).toBe(20);
});

test('throws for unregistered token', () => {
  const c = new Container();
  expect(() => c.resolve('unknown')).toThrow();
});

// __hidden__
test('factory is called only once even with multiple resolves', () => {
  const c = new Container();
  let calls = 0;
  c.register('once', () => { calls++; return {}; });
  c.resolve('once');
  c.resolve('once');
  c.resolve('once');
  expect(calls).toBe(1);
});

solution:
export class Container {
  constructor() {
    this._factories = new Map();
    this._instances = new Map();
  }

  register(token, factory) {
    this._factories.set(token, factory);
  }

  resolve(token) {
    if (this._instances.has(token)) return this._instances.get(token);
    if (!this._factories.has(token)) throw new Error(`No registration for token: ${token}`);
    const instance = this._factories.get(token)(this);
    this._instances.set(token, instance);
    return instance;
  }
}
